import type { Channel } from '../types';

// A valid broadcaster LCN overrides the index of the channel in the IPTV list.
export function channelLcn(channel: Pick<Channel, 'channelNumber'>, index: number): number {
  const declared = channel.channelNumber;
  return typeof declared === 'number' && Number.isInteger(declared) && declared > 0
    ? declared : index + 1;
}

// Explicit LCN always wins, even when another unnumbered item uses that position.
export function findChannelIndexByLcn(channels: readonly Channel[], lcn: number): number {
  if (!Number.isInteger(lcn) || lcn <= 0) return -1;
  const declared = channels.findIndex(ch => ch.channelNumber === lcn);
  if (declared >= 0) return declared;
  return channels.findIndex((ch, index) =>
    channelLcn(ch, index) === lcn &&
    !(typeof ch.channelNumber === 'number' && Number.isInteger(ch.channelNumber) && ch.channelNumber > 0));
}

