/** Accessible D-pad number entry for non-rooted LG webOS TVs.
 * Yellow opens the dialog during live TV; arrow keys and OK work without
 * needing any number key events from webOS. No background listeners when closed.
 */
const KEYS = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'Cancella', '0', 'Vai'];

export class VirtualNumpad {
  private dialog: HTMLElement | null = null;
  private selected = 0;
  private digits = '';
  private message = '';

  constructor(private readonly tune: (lcn: number) => boolean) {}

  open(): void {
    if (this.dialog) return;
    this.selected = 0;
    this.digits = '';
    this.message = '';
    const el = document.createElement('div');
    el.className = 'lcn-keypad';
    el.setAttribute('role', 'dialog');
    el.setAttribute('aria-label', 'Tastierino LCN');
    el.innerHTML = '<div class="lcn-keypad-panel">'
      + '<div class="lcn-keypad-title">Vai al canale LCN</div>'
      + '<div class="lcn-keypad-display" aria-live="polite"></div>'
      + '<div class="lcn-keypad-grid"></div>'
      + '<div class="lcn-keypad-hint">Frecce: sposta · OK: scegli · Indietro: chiudi</div>'
      + '</div>';
    const grid = el.querySelector('.lcn-keypad-grid')!;
    for (let i = 0; i < KEYS.length; i++) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'lcn-keypad-key';
      button.textContent = KEYS[i];
      button.setAttribute('data-pad-pos', String(i));
      grid.appendChild(button);
    }
    el.addEventListener('click', (e) => {
      const target = e.target as Element;
      const button = target.closest('[data-pad-pos]');
      if (button) {
        this.selected = Number(button.getAttribute('data-pad-pos'));
        this.press();
      } else if (target === el) {
        this.close();
      }
    });
    document.body.appendChild(el);
    this.dialog = el;
    this.draw();
    // window capture fires before the application's document-level key listeners.
    window.addEventListener('keydown', this.onKey, true);
  }

  close(): void {
    window.removeEventListener('keydown', this.onKey, true);
    if (this.dialog) this.dialog.parentNode?.removeChild(this.dialog);
    this.dialog = null;
  }

  private onKey = (e: KeyboardEvent): void => {
    if (!this.dialog) return;
    const code = e.keyCode;
    if (![37, 38, 39, 40, 13, 461, 27, 8].includes(code)
      && (code < 48 || code > 57)) return;
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();
    if (code === 461 || code === 27) { this.close(); return; }
    if (code === 8) { this.digits = this.digits.slice(0, -1); this.message = ''; }
    else if (code === 13) this.press();
    else if (code >= 48 && code <= 57) this.push(String(code - 48));
    else {
      const row = Math.floor(this.selected / 3);
      const col = this.selected % 3;
      if (code === 37) this.selected = row * 3 + Math.max(0, col - 1);
      if (code === 39) this.selected = row * 3 + Math.min(2, col + 1);
      if (code === 38) this.selected = Math.max(0, row - 1) * 3 + col;
      if (code === 40) this.selected = Math.min(3, row + 1) * 3 + col;
    }
    if (this.dialog) this.draw();
  };

  private push(value: string): void {
    if (this.digits.length < 4) this.digits += value;
    this.message = '';
  }

  private press(): void {
    const value = KEYS[this.selected];
    if (value === 'Cancella') {
      this.digits = this.digits.slice(0, -1);
    } else if (value === 'Vai') {
      const number = Number(this.digits);
      if (number > 0 && this.tune(number)) { this.close(); return; }
      this.message = this.digits ? 'LCN non presente nella playlist' : 'Inserisci un numero';
    } else this.push(value);
    this.draw();
  }

  private draw(): void {
    if (!this.dialog) return;
    const display = this.dialog.querySelector('.lcn-keypad-display')!;
    display.textContent = this.message || (this.digits || '—');
    const buttons = this.dialog.querySelectorAll('.lcn-keypad-key');
    for (let i = 0; i < buttons.length; i++) {
      buttons[i].classList.toggle('lcn-keypad-key--focused', i === this.selected);
    }
  }
}

