/* Accessible TV remote D-pad overlay. Does not need root or numeric key events. */
.lcn-keypad {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9998;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, .78);
}
.lcn-keypad-panel {
  width: 420px;
  padding: 30px;
  background: #111927;
  color: #fff;
  border-radius: 18px;
  box-shadow: 0 0 0 3px #4b6480, 0 16px 60px #000;
}
.lcn-keypad-title { text-align: center; font-size: 27px; font-weight: bold; }
.lcn-keypad-display {
  margin: 22px 0;
  padding: 16px 8px;
  min-height: 52px;
  text-align: center;
  font-size: 31px;
  color: #ffe16b;
  background: #0b111b;
  border-radius: 8px;
}
.lcn-keypad-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
}
.lcn-keypad-key {
  box-sizing: border-box;
  width: 31%;
  height: 66px;
  margin-bottom: 10px;
  background: #243449;
  border: 3px solid transparent;
  border-radius: 9px;
  color: #fff;
  font-size: 24px;
  font-weight: bold;
}
.lcn-keypad-key--focused {
  background: #174766;
  color: #fff;
  border-color: #ffe16b;
  box-shadow: inset 0 0 0 1px #ffe16b;
}
.lcn-keypad-hint {
  padding-top: 8px;
  color: #bdc8d8;
  font-size: 16px;
  text-align: center;
}
